import json,glob,subprocess
s=set()
for p in ['state/materials.jsonl']+glob.glob('state/materials.d/*.jsonl'):
    for l in open(p,encoding='utf-8'):
        l=l.strip()
        if l: s.add((json.loads(l).get('origin') or {}).get('commit',''))
print(len(s), sum(subprocess.run(['git','cat-file','-t',c],capture_output=True).returncode==0 for c in s if c))
